  `instansi` varchar(255) NOT NULL DEFAULT 'Dinas Pekerjaan Umum dan Penataan Ruang Kabupaten Demak',
  `pemerintah_daerah` varchar(150) DEFAULT 'Pemerintah Kabupaten Demak',
